node - <<'NODE'
const { EventRepository } = require('./src/repositories/eventRepository');
const { AnalysisRepository } = require('./src/repositories/analysisRepository');
const { StoryRepository } = require('./src/repositories/storyRepository');
const { StoryClusteringService } = require('./src/services/storyClusteringService');
const { storagePath, analysisStoragePath, storyStoragePath } = require('./src/config');
const { FinancialNLPipeline } = require('./src/nlp/nlpPipeline');
const { SourceAdapterRegistry } = require('./src/adapters/sourceRegistry');
const { IngestionService } = require('./src/services/ingestionService');
const repository = new EventRepository(storagePath);
const analysisRepository = new AnalysisRepository(analysisStoragePath);
const storyRepository = new StoryRepository(storyStoragePath);
const service = new IngestionService({ repository, sourceRegistry: new SourceAdapterRegistry() });
const storyService = new StoryClusteringService({ eventRepository: repository, analysisRepository, storyRepository });
const e1 = service.ingestOne({source:'news', source_event_id:'s1', title:'Company X faces regulatory investigation', content:'Authorities are investigating Company X after compliance concerns.', published_at:new Date().toISOString(), language:'en', event_type:'regulatory_action'});
const a1 = new FinancialNLPipeline().process(e1);
analysisRepository.save(a1);
const e2 = service.ingestOne({source:'major_news', source_event_id:'s2', title:'Regulator launches probe into Company X', content:'A regulator launched a probe into Company X after compliance issues were identified.', published_at:new Date().toISOString(), language:'en', event_type:'regulatory_action'});
const a2 = new FinancialNLPipeline().process(e2);
analysisRepository.save(a2);
console.log('event1', e1.id, e1.title, 'entities', a1.entities, 'topics', a2.topics);
console.log('similarity', storyService.getSimilarityScore(e1,a1,e2,a2));
const match = storyService.findMatchingStory(e2,a2);
console.log('match', match && match.story && {id:match.story.id, title:match.story.title, score:match.score, source_count:match.story.source_count});
console.log('all stories', storyService.listStories());
NODE
